//! The Poseidon permutation (Grassi, Khovratovich, Rechberger, Roy,
//! Schofnegger, USENIX Security 2021, ePrint 2019/458).
//!
//! A Poseidon instance is a width `T`, numbers of full and partial rounds,
//! and an S-box `x^alpha` with `gcd(alpha, p - 1) = 1` (so that it is a
//! permutation). Its round constants and its MDS matrix are generated by the
//! Grain LFSR ([`grain`]) from those parameters, so [`Poseidon::new`] works
//! over any prime field. The permutation plugs into the transcript crate's
//! [`Duplex`] sponge as a [`Permutation`].
//!
//! [`pallas_base`] and [`vesta_base`] are the instances of Halo 2 and Orchard
//! (`P128Pow5T3`: width 3, 8 full and 56 partial rounds, `x^5`) over the two
//! Pasta fields, checked against the Zcash test vectors.
//!
//! ```
//! use arrabbiata_field::Field;
//! use arrabbiata_pasta::Fp;
//! use arrabbiata_poseidon::{PoseidonSponge, pallas_base};
//! use arrabbiata_transcript::{Duplex, Transcript};
//!
//! let mut sponge: PoseidonSponge<Fp> = Duplex::new(pallas_base(), 0);
//! sponge.absorb(Fp::from_u64(42));
//! let challenge = sponge.squeeze();
//! # let _ = challenge;
//! ```

#![no_std]

extern crate alloc;

pub mod grain;

use alloc::vec::Vec;

use arrabbiata_bn254::{Fq as Bn254Fq, Fr as Bn254Fr};
use arrabbiata_field::{Field, PrimeField};
use arrabbiata_pasta::{Fp, Fq};
use arrabbiata_transcript::{Duplex, Permutation};

use crate::grain::Grain;

/// A Poseidon permutation of `F^T`.
///
/// ```
/// use arrabbiata_field::Field;
/// use arrabbiata_pasta::Fp;
/// use arrabbiata_poseidon::Poseidon;
/// let poseidon = Poseidon::<Fp, 3>::new(8, 56, 5);
/// let mut state = [Fp::ZERO, Fp::ONE, Fp::from_u64(2)];
/// poseidon.permute_state(&mut state);
/// assert_ne!(state, [Fp::ZERO, Fp::ONE, Fp::from_u64(2)]);
/// ```
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Poseidon<F, const T: usize> {
    full_rounds: usize,
    partial_rounds: usize,
    alpha: u64,
    round_constants: Vec<[F; T]>,
    mds: [[F; T]; T],
}

impl<F, const T: usize> Poseidon<F, T>
where
    F: PrimeField,
{
    /// The instance with `full_rounds` full rounds (an even number, half
    /// before and half after the partial rounds), `partial_rounds` partial
    /// rounds and the S-box `x^alpha`, with Grain-generated constants and
    /// the first MDS matrix the generator produces.
    ///
    /// # Panics
    ///
    /// If `full_rounds` is odd, or if `x^alpha` is not a permutation of `F`
    /// (`alpha` divides `p - 1`).
    ///
    /// ```
    /// use arrabbiata_pasta::Fq;
    /// use arrabbiata_poseidon::Poseidon;
    /// let p = Poseidon::<Fq, 3>::new(8, 56, 5);
    /// assert_eq!(p.round_constants().len(), 64);
    /// ```
    #[must_use]
    pub fn new(full_rounds: usize, partial_rounds: usize, alpha: u64) -> Self {
        assert!(
            full_rounds.is_multiple_of(2),
            "the full rounds are split in two halves"
        );
        assert!(
            alpha > 1 && minus_one_mod(F::ZERO - F::ONE, alpha) != 0,
            "x^alpha is a permutation only if alpha does not divide p - 1"
        );
        let mut grain = Grain::<F>::new(T as u16, full_rounds as u16, partial_rounds as u16);
        let mut round_constants = Vec::with_capacity(full_rounds + partial_rounds);
        let mut r = 0;
        while r < full_rounds + partial_rounds {
            let mut row = [F::ZERO; T];
            let mut i = 0;
            while i < T {
                row[i] = grain.next_field_element();
                i += 1;
            }
            round_constants.push(row);
            r += 1;
        }
        let mds = cauchy_mds(&mut grain);
        Self {
            full_rounds,
            partial_rounds,
            alpha,
            round_constants,
            mds,
        }
    }

    /// The round constants, one row per round.
    ///
    /// ```
    /// use arrabbiata_pasta::Fp;
    /// use arrabbiata_poseidon::pallas_base;
    /// assert_eq!(pallas_base().round_constants()[0].len(), 3);
    /// ```
    #[must_use]
    pub fn round_constants(&self) -> &[[F; T]] {
        &self.round_constants
    }

    /// The MDS matrix.
    ///
    /// ```
    /// use arrabbiata_field::Field;
    /// use arrabbiata_poseidon::pallas_base;
    /// assert!(!pallas_base().mds()[0][0].is_zero());
    /// ```
    #[must_use]
    pub const fn mds(&self) -> &[[F; T]; T] {
        &self.mds
    }

    fn apply_mds(&self, state: &mut [F; T]) {
        let mut out = [F::ZERO; T];
        let mut i = 0;
        while i < T {
            let mut j = 0;
            while j < T {
                out[i] = out[i] + self.mds[i][j] * state[j];
                j += 1;
            }
            i += 1;
        }
        *state = out;
    }

    /// Apply the permutation in place: `full_rounds / 2` full rounds,
    /// `partial_rounds` partial rounds (S-box on the first word only), and
    /// `full_rounds / 2` full rounds; each round adds its constants, applies
    /// the S-box, then the MDS matrix.
    ///
    /// ```
    /// use arrabbiata_field::Field;
    /// use arrabbiata_pasta::Fp;
    /// use arrabbiata_poseidon::pallas_base;
    /// let mut a = [Fp::ZERO; 3];
    /// let mut b = [Fp::ZERO; 3];
    /// pallas_base().permute_state(&mut a);
    /// pallas_base().permute_state(&mut b);
    /// assert_eq!(a, b);
    /// ```
    pub fn permute_state(&self, state: &mut [F; T]) {
        let half = self.full_rounds / 2;
        let mut round = 0;
        while round < self.full_rounds + self.partial_rounds {
            let constants = &self.round_constants[round];
            let full = round < half || round >= half + self.partial_rounds;
            let mut i = 0;
            while i < T {
                state[i] = state[i] + constants[i];
                if full || i == 0 {
                    state[i] = state[i].pow(self.alpha);
                }
                i += 1;
            }
            self.apply_mds(state);
            round += 1;
        }
    }
}

impl<F, const T: usize> Permutation<F, T> for Poseidon<F, T>
where
    F: PrimeField,
{
    fn permute(&self, state: &mut [F; T]) {
        self.permute_state(state);
    }
}

/// The Cauchy matrix `1 / (x_i + y_j)` on the first `2 T` distinct elements
/// the generator yields (without rejection), as in the reference.
fn cauchy_mds<F, const T: usize>(grain: &mut Grain<F>) -> [[F; T]; T]
where
    F: PrimeField,
{
    loop {
        let mut values = Vec::with_capacity(2 * T);
        let mut k = 0;
        while k < 2 * T {
            values.push(grain.next_field_element_without_rejection());
            k += 1;
        }
        if !all_distinct(&values) {
            continue;
        }
        let mut mds = [[F::ZERO; T]; T];
        let mut i = 0;
        while i < T {
            let mut j = 0;
            while j < T {
                match (values[i] + values[T + j]).inverse() {
                    Some(inverse) => mds[i][j] = inverse,
                    None => panic!("x_i + y_j = 0 in the Cauchy matrix"),
                }
                j += 1;
            }
            i += 1;
        }
        return mds;
    }
}

fn all_distinct<F>(values: &[F]) -> bool
where
    F: Field,
{
    let mut i = 0;
    while i < values.len() {
        let mut j = i + 1;
        while j < values.len() {
            if values[i] == values[j] {
                return false;
            }
            j += 1;
        }
        i += 1;
    }
    true
}

/// `(p - 1) mod m`, from the canonical limbs of `p - 1`.
fn minus_one_mod<F>(minus_one: F, m: u64) -> u64
where
    F: PrimeField,
{
    let mut acc: u128 = 0;
    let mut i = F::LIMBS;
    while i > 0 {
        i -= 1;
        acc = ((acc << 64) | u128::from(minus_one.limb(i))) % u128::from(m);
    }
    acc as u64
}

/// A duplex sponge over Poseidon of width 3 and rate 2.
pub type PoseidonSponge<F> = Duplex<F, Poseidon<F, 3>, 3, 2>;

/// Poseidon over the Pallas base field `Fp`: width 3, 8 full and 56 partial
/// rounds, `x^5`. The `P128Pow5T3` instance of Halo 2 and Orchard.
///
/// ```
/// use arrabbiata_poseidon::pallas_base;
/// assert_eq!(pallas_base().round_constants().len(), 64);
/// ```
#[must_use]
pub fn pallas_base() -> Poseidon<Fp, 3> {
    Poseidon::new(8, 56, 5)
}

/// Poseidon over the Vesta base field `Fq`: width 3, 8 full and 56 partial
/// rounds, `x^5`. The `P128Pow5T3` instance of Halo 2.
///
/// ```
/// use arrabbiata_poseidon::vesta_base;
/// assert_eq!(vesta_base().round_constants().len(), 64);
/// ```
#[must_use]
pub fn vesta_base() -> Poseidon<Fq, 3> {
    Poseidon::new(8, 56, 5)
}

/// A Poseidon sponge over `Fp`, separated by `domain`.
///
/// ```
/// use arrabbiata_poseidon::pallas_sponge;
/// use arrabbiata_transcript::Transcript;
/// let mut t = pallas_sponge(1);
/// let _ = t.squeeze();
/// ```
#[must_use]
pub fn pallas_sponge(domain: u64) -> PoseidonSponge<Fp> {
    Duplex::new(pallas_base(), domain)
}

/// A Poseidon sponge over `Fq`, separated by `domain`.
///
/// ```
/// use arrabbiata_poseidon::vesta_sponge;
/// use arrabbiata_transcript::Transcript;
/// let mut t = vesta_sponge(1);
/// let _ = t.squeeze();
/// ```
#[must_use]
pub fn vesta_sponge(domain: u64) -> PoseidonSponge<Fq> {
    Duplex::new(vesta_base(), domain)
}

/// Poseidon over the BN254 scalar field: width 3, 8 full and 57 partial
/// rounds, `x^5` (the round numbers of the Poseidon paper for a 254-bit
/// field at 128 bits of security). Constants are Grain-generated with the
/// first MDS matrix; no compatibility with another implementation is
/// claimed.
///
/// ```
/// use arrabbiata_poseidon::bn254_scalar;
/// assert_eq!(bn254_scalar().round_constants().len(), 65);
/// ```
#[must_use]
pub fn bn254_scalar() -> Poseidon<Bn254Fr, 3> {
    Poseidon::new(8, 57, 5)
}

/// Poseidon over the BN254 base field, with the parameters of
/// [`bn254_scalar`].
///
/// ```
/// use arrabbiata_poseidon::bn254_base;
/// assert_eq!(bn254_base().round_constants().len(), 65);
/// ```
#[must_use]
pub fn bn254_base() -> Poseidon<Bn254Fq, 3> {
    Poseidon::new(8, 57, 5)
}

/// A Poseidon sponge over the BN254 scalar field, separated by `domain`.
///
/// ```
/// use arrabbiata_poseidon::bn254_scalar_sponge;
/// use arrabbiata_transcript::Transcript;
/// let _ = bn254_scalar_sponge(0).squeeze();
/// ```
#[must_use]
pub fn bn254_scalar_sponge(domain: u64) -> PoseidonSponge<Bn254Fr> {
    Duplex::new(bn254_scalar(), domain)
}

/// A Poseidon sponge over the BN254 base field, separated by `domain`.
///
/// ```
/// use arrabbiata_poseidon::bn254_base_sponge;
/// use arrabbiata_transcript::Transcript;
/// let _ = bn254_base_sponge(0).squeeze();
/// ```
#[must_use]
pub fn bn254_base_sponge(domain: u64) -> PoseidonSponge<Bn254Fq> {
    Duplex::new(bn254_base(), domain)
}
